def build_vocabulary() -> list[dict]:
    entries: list[dict] = []
    for length, words in sorted(WORDS_BY_LENGTH.items()):
        for word in words:
            entries.append({
                "id": f"word_{word}",
                "word": word,
                "word_length": length,
                "category": "general",
                "difficulty": max(1, min(3, length - 1)),
                "starting_letter": word[0].upper() if word else "",
                "prompt": f"Touch the {word}",
                "speech_prompt": f"Say {word}",
                "confusable_with": [],
            })
    return entries


if __name__ == "__main__":
    entries = build_vocabulary()
    path = ROOT / "data" / "vocabulary.json"
    path.write_text(json.dumps(entries, indent=2), encoding="utf-8")
    counts = {}
    for entry in entries:
        counts[entry["word_length"]] = counts.get(entry["word_length"], 0) + 1
    print(f"Wrote {len(entries)} words to {path}")
    for length, count in sorted(counts.items()):
        print(f"  length {length}: {count} words")
